import Foundation

extension Recipe {
    static let wrap = "\n\nText:\n\"\"\"\n{{input}}\n\"\"\""

    public static let builtins: [Recipe] = [
        // MARK: Understand
        Recipe(id: "summarize", title: "Summarize", summary: "Summary in your chosen style and length. Handles long documents.",
               symbol: "text.append", category: "Understand",
               instructions: "You summarize text accurately. Use only facts that appear in the text. Never add information.",
               template: "Summarize the text as {{style}}. Length: {{length}}." + wrap,
               params: [RecipeParam(key: "style", label: "Style", defaultValue: "bullet points", choices: ["bullet points", "a paragraph", "an executive summary", "a one-line TL;DR"]),
                        RecipeParam(key: "length", label: "Length", defaultValue: "short", choices: ["short", "medium", "detailed"])],
               temperature: 0.3, permissive: true, long: .reduce, builtin: true),
        Recipe(id: "key-points", title: "Key points", summary: "The five to eight points that matter most.",
               symbol: "list.star", category: "Understand",
               instructions: "You find the most important points in text. Be specific. Use only the text.",
               template: "List the 5 to 8 most important points in the text as short bullet points." + wrap,
               temperature: 0.3, permissive: true, long: .reduce, builtin: true),
        Recipe(id: "eli5", title: "Explain simply", summary: "Explains the text so a twelve-year-old would get it.",
               symbol: "graduationcap", category: "Understand",
               instructions: "You explain complex ideas in plain, friendly language with a concrete everyday example.",
               template: "Explain what this text is about in simple terms a twelve-year-old would understand." + wrap,
               temperature: 0.5, permissive: true, long: .reduce, builtin: true),
        Recipe(id: "ask", title: "Ask the document", summary: "Answers a question using only the text you give it.",
               symbol: "questionmark.bubble", category: "Understand",
               instructions: "Answer questions using only the provided text. If the text doesn't contain the answer, say \"The text doesn't say.\"",
               template: "Question: {{question}}" + wrap,
               params: [RecipeParam(key: "question", label: "Question", defaultValue: "What is the main conclusion?")],
               temperature: 0.2, permissive: true, long: .reduce, builtin: true),
        Recipe(id: "outline", title: "Outline", summary: "A clean hierarchical outline of the content.",
               symbol: "list.bullet.indent", category: "Understand",
               instructions: "You produce clear, hierarchical Markdown outlines of documents.",
               template: "Create a nested Markdown outline of this text with short headings." + wrap,
               temperature: 0.3, permissive: true, long: .reduce, builtin: true),

        // MARK: Write
        Recipe(id: "rewrite", title: "Rewrite", summary: "Rewrites text in a new tone while keeping the meaning.",
               symbol: "pencil.and.outline", category: "Write",
               instructions: "You rewrite text in the requested tone. Keep every fact and the original meaning. Output only the rewritten text.",
               template: "Rewrite the text in a {{tone}} tone." + wrap,
               params: [RecipeParam(key: "tone", label: "Tone", defaultValue: "professional",
                                    choices: ["professional", "friendly", "concise", "formal", "casual", "persuasive", "plain English", "enthusiastic"])],
               temperature: 0.6, permissive: true, long: .concatenate, builtin: true),
        Recipe(id: "proofread", title: "Proofread", summary: "Fixes spelling, grammar and punctuation. Returns the corrected text.",
               symbol: "checkmark.seal", category: "Write",
               instructions: "You are a meticulous copy editor. Fix spelling, grammar and punctuation only. Keep the author's voice and wording otherwise. Output only the corrected text.",
               template: "Proofread and correct this text." + wrap,
               temperature: 0.1, permissive: true, long: .concatenate, builtin: true),
        Recipe(id: "translate", title: "Translate", summary: "Translates into any of the model's supported languages.",
               symbol: "character.bubble", category: "Write",
               instructions: "You are a professional translator. Translate faithfully and naturally. Output only the translation.",
               template: "Translate this text into {{language}}." + wrap,
               params: [RecipeParam(key: "language", label: "Language", defaultValue: "Spanish",
                                    choices: ["Spanish", "French", "German", "Italian", "Portuguese", "Japanese", "Korean", "Chinese (Simplified)", "Dutch", "Swedish", "Turkish", "Vietnamese", "Danish", "Norwegian", "English"])],
               temperature: 0.2, permissive: true, long: .concatenate, builtin: true),
        Recipe(id: "title", title: "Headlines", summary: "Five title or headline options.",
               symbol: "textformat.size", category: "Write",
               instructions: "You write sharp, accurate titles. No clickbait.",
               template: "Write 5 title options for this text, one per line, numbered." + wrap,
               temperature: 0.8, permissive: true, long: .reduce, builtin: true),
        Recipe(id: "email-reply", title: "Email reply", summary: "Drafts a reply to an email with the intent you choose.",
               symbol: "arrowshape.turn.up.left", category: "Write",
               instructions: "You write clear, polite, brief email replies. Output only the email body.",
               template: "Write a reply to this email. Intent: {{intent}}." + wrap,
               params: [RecipeParam(key: "intent", label: "Intent", defaultValue: "accept",
                                    choices: ["accept", "decline politely", "ask for more information", "say thank you", "propose a different time"])],
               temperature: 0.6, permissive: true, long: .reject, builtin: true),

        // MARK: Extract (structured)
        Recipe(id: "sentiment", title: "Sentiment", summary: "Sentiment label, confidence and a one-line reason, as JSON.",
               symbol: "face.smiling", category: "Extract",
               instructions: "You analyze the sentiment of text carefully and calibrate your confidence.",
               template: "Analyze the sentiment of this text." + wrap,
               params: [],
               schema: #"{"type":"object","title":"Sentiment","properties":{"sentiment":{"type":"string","enum":["positive","neutral","negative","mixed"]},"confidence":{"type":"number","minimum":0,"maximum":1},"reason":{"type":"string","description":"One short sentence"}},"required":["sentiment","confidence","reason"],"x-order":["sentiment","confidence","reason"]}"#,
               temperature: 0.1, permissive: true, long: .merge, builtin: true),
        Recipe(id: "classify", title: "Classify", summary: "Picks the best label from your own list, as JSON.",
               symbol: "tray.2", category: "Extract",
               instructions: "You classify text into exactly one of the allowed labels.",
               template: "Classify this text. Allowed labels: {{labels}}." + wrap,
               params: [RecipeParam(key: "labels", label: "Labels (comma-separated)", defaultValue: "bug report, feature request, question, praise, complaint")],
               schema: #"{"type":"object","title":"Classification","properties":{"label":{"type":"string","enum":{{labels_json}}},"confidence":{"type":"number","minimum":0,"maximum":1},"reason":{"type":"string"}},"required":["label","confidence","reason"],"x-order":["label","confidence","reason"]}"#,
               temperature: 0.1, permissive: true, long: .merge, builtin: true),
        Recipe(id: "entities", title: "Entities", summary: "People, organizations, places, dates and products, as JSON.",
               symbol: "person.2.crop.square.stack", category: "Extract",
               instructions: "You extract named entities exactly as they appear in the text. Don't invent any.",
               template: "Extract the named entities from this text." + wrap,
               schema: #"{"type":"object","title":"Entities","properties":{"people":{"type":"array","items":{"type":"string"}},"organizations":{"type":"array","items":{"type":"string"}},"places":{"type":"array","items":{"type":"string"}},"dates":{"type":"array","items":{"type":"string"}},"products":{"type":"array","items":{"type":"string"}}},"required":["people","organizations","places","dates","products"],"x-order":["people","organizations","places","dates","products"]}"#,
               temperature: 0.1, permissive: true, long: .merge, builtin: true),
        Recipe(id: "action-items", title: "Action items", summary: "Tasks with owner, due date and priority, as JSON.",
