               schema: #"{"type":"object","title":"ActionItems","properties":{"items":{"type":"array","items":{"type":"object","title":"ActionItem","properties":{"task":{"type":"string"},"owner":{"type":"string","description":"Person responsible, or unassigned"},"due":{"type":"string","description":"Due date if stated, otherwise none"},"priority":{"type":"string","enum":["high","medium","low"]}},"required":["task","owner","due","priority"],"x-order":["task","owner","due","priority"]}}},"required":["items"]}"#,
               temperature: 0.1, permissive: true, long: .merge, builtin: true),
        Recipe(id: "meeting-notes", title: "Meeting notes", summary: "Summary, decisions, action items and open questions from a transcript.",
               symbol: "person.3.sequence", category: "Extract",
               instructions: "You turn meeting transcripts into structured notes. Use only what was said.",
               template: "Turn this meeting transcript into structured notes." + wrap,
               schema: #"{"type":"object","title":"MeetingNotes","properties":{"summary":{"type":"string","description":"Two or three sentences"},"decisions":{"type":"array","items":{"type":"string"}},"action_items":{"type":"array","items":{"type":"object","title":"MeetingAction","properties":{"task":{"type":"string"},"owner":{"type":"string"}},"required":["task","owner"],"x-order":["task","owner"]}},"open_questions":{"type":"array","items":{"type":"string"}}},"required":["summary","decisions","action_items","open_questions"],"x-order":["summary","decisions","action_items","open_questions"]}"#,
               temperature: 0.2, permissive: true, long: .merge, builtin: true),
        Recipe(id: "tags", title: "Tags", summary: "Topic tags using Apple's content-tagging model.",
               symbol: "tag", category: "Extract",
               instructions: "Tag the text with short, lowercase topic tags.",
               template: "{{input}}",
               params: [RecipeParam(key: "max_tags", label: "Maximum tags", defaultValue: "6", choices: ["3", "6", "10"])],
               schema: #"{"type":"object","title":"Tags","properties":{"tags":{"type":"array","maxItems":{{max_tags}},"items":{"type":"string"}}},"required":["tags"]}"#,
               temperature: 0.1, useCase: .tagging, permissive: true, long: .merge, builtin: true),
        Recipe(id: "keywords", title: "Keywords", summary: "Search keywords and key phrases, as JSON.",
               symbol: "magnifyingglass", category: "Extract",
               instructions: "You pick the keywords and phrases someone would search for to find this text.",
               template: "Extract up to 12 keywords or key phrases from this text." + wrap,
               schema: #"{"type":"object","title":"Keywords","properties":{"keywords":{"type":"array","maxItems":12,"items":{"type":"string"}}},"required":["keywords"]}"#,
               temperature: 0.2, permissive: true, long: .merge, builtin: true),
        Recipe(id: "quiz", title: "Quiz", summary: "Study questions with answers, as JSON.",
               symbol: "brain.head.profile", category: "Extract",
               instructions: "You write clear study questions whose answers are found in the text.",
               template: "Write {{count}} quiz questions with short answers based on this text." + wrap,
               params: [RecipeParam(key: "count", label: "Questions", defaultValue: "5", choices: ["3", "5", "8"])],
               schema: #"{"type":"object","title":"Quiz","properties":{"questions":{"type":"array","maxItems":10,"items":{"type":"object","title":"QuizItem","properties":{"question":{"type":"string"},"answer":{"type":"string"}},"required":["question","answer"],"x-order":["question","answer"]}}},"required":["questions"]}"#,
               temperature: 0.5, permissive: true, long: .merge, builtin: true),

        // MARK: Code
        Recipe(id: "explain-code", title: "Explain code", summary: "What a piece of code does, step by step.",
               symbol: "chevron.left.forwardslash.chevron.right", category: "Code",
               instructions: "You are a senior engineer. Explain code accurately and concisely. Don't invent behavior that isn't in the code.",
               template: "Explain what this code does, then list any obvious risks." + "\n\nCode:\n```\n{{input}}\n```",
               temperature: 0.2, permissive: true, long: .reduce, builtin: true),
        Recipe(id: "commit-message", title: "Commit message", summary: "A Conventional Commits message from a diff.",
               symbol: "point.topleft.down.to.point.bottomright.curvepath", category: "Code",
               instructions: "You write Conventional Commits messages: a type(scope): subject line under 72 characters, a blank line, then a short body of bullet points. Output only the message.",
               template: "Write a commit message for this diff." + "\n\nDiff:\n```\n{{input}}\n```",
               temperature: 0.2, permissive: true, long: .reduce, builtin: true),
        Recipe(id: "regex", title: "Regex helper", summary: "Builds a regular expression from a plain-English description.",
               symbol: "asterisk", category: "Code",
               instructions: "You write correct regular expressions. Give the pattern on the first line, then one line explaining it.",
               template: "Write a regular expression that matches: {{input}}",
               temperature: 0.1, long: .reject, builtin: true),
    ]
}
